window.MOTIF_CATALOG_CHUNKS[10]={"cards":[{"id":"MEJE-KW-001083","row_version":1,"title":"아프로 헤어의 액션 영웅","original":"Afro Asskicker","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"아프로 헤어를 외형의 중요한 특징으로 지닌 격투·액션 인물상. 머리 모양이 인물의 개성과 시대적 이미지에 쓰이되, 행동과 성격을 외형 하나로 환원하지 않는다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-001083/index.html"},{"id":"MEJE-KW-001084","row_version":1,"title":"아프로비트","original":"Afrobeat","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03","ML-T00527"],"summary":"서아프리카의 리듬과 재즈·펑크 등의 요소가 결합한 음악 장르. 반복되는 리듬과 관악기, 긴 흐름이 춤과 사회적 메시지를 함께 담을 수 있다.","accent":"#8A687E","tab":"#9B8A6F","facet":"장르","bookmark":"음악 장르·재즈·민속음악","entry_url":"cards/MEJE-KW-001084/index.html"},{"id":"MEJE-KW-001085","row_version":1,"title":"아프로퓨처리즘","original":"Afrofuturism","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"흑인의 역사와 문화적 경험을 미래·과학기술·환상적 상상과 결합해 새로운 세계를 그리는 예술 경향. 누가 미래를 만들고 그 안에서 살아가는지를 다시 묻는다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-001085/index.html"},{"id":"MEJE-KW-001086","row_version":1,"title":"위기 직후의 치료 갈등","original":"After-Action Healing Drama","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"전투나 추격이 끝난 뒤 다친 인물을 살리려는 일이 새로운 긴장의 중심이 되는 흐름. 위험을 넘긴 뒤에도 생존과 관계의 문제가 남아 있음을 보여 준다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-001086/index.html"},{"id":"MEJE-KW-001087","row_version":1,"title":"사건 뒤 상처를 돌봐 줌","original":"After-Action Patch-Up","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10","ML-T01011","ML-T01016"],"summary":"위험한 일을 마친 뒤 한 인물이 다른 인물의 가벼운 상처를 살피는 장면. 몸의 상처를 돌보는 동안 감사와 미안함, 가까워지는 마음을 드러낸다.","accent":"#9D7C82","tab":"#7D8FA3","facet":"관계","bookmark":"돌봄 관계","entry_url":"cards/MEJE-KW-001087/index.html"},{"id":"MEJE-KW-001088","row_version":1,"title":"플레이 결과를 보고서처럼 서술","original":"After-Action Report","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":null,"parent_id":null,"tag_path":["ML-F04","ML-T00576","ML-T00579"],"summary":"게임 플레이에서 일어난 사건을 보고서나 기록문의 형식으로 다시 들려주는 창작 방식. 실제 진행의 순서를 인물과 원인, 결과가 있는 이야기로 재구성한다.","accent":"#7E7970","tab":"#A58A4E","facet":"형식·구성·규모","bookmark":"기록물 형식","entry_url":"cards/MEJE-KW-001088/index.html"},{"id":"MEJE-KW-001089","row_version":1,"title":"사건 뒤 악역을 되짚는 대화","original":"After-Action Villain Analysis","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"갈등이 잠시 끝난 뒤 인물들이 악역의 행동과 동기를 차분히 정리하는 장면. 사건의 의미를 다시 묶고 남은 관계의 변화를 확인한다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-001089/index.html"},{"id":"MEJE-KW-001090","row_version":1,"title":"모험 뒤 원래 모습으로 돌아감","original":"After-Adventure Restoration","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"큰 여정 뒤에 달라진 몸이나 소유물, 생활 방식이 이야기 시작 전의 상태로 되돌아가는 결말 처리. 변화의 흔적을 얼마나 남기는지가 작품의 마무리 인상을 바꾼다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-001090/index.html"},{"id":"MEJE-KW-001091","row_version":1,"title":"보스전 뒤 자원 회복","original":"After Boss Recovery","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25","ML-T02106"],"summary":"게임에서 보스를 쓰러뜨린 직후 체력이나 장비 자원을 보충할 기회를 주는 설계. 큰 전투를 넘긴 보상과 다음 구간의 준비가 한 번에 이뤄진다. 전투 종료마다 자동 회복보다 특정 전투에 한정된다.","accent":"#667E94","tab":"#528982","facet":"게임·상호작용","bookmark":"전투·경쟁","entry_url":"cards/MEJE-KW-001091/index.html"},{"id":"MEJE-KW-001092","row_version":1,"title":"전투 종료마다 자동 회복","original":"After-Combat Recovery","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25","ML-T02106"],"summary":"게임에서 전투가 끝날 때마다 인물의 체력이나 행동 자원이 자동으로 돌아오는 규칙. 개별 전투의 긴장은 유지하면서 다음 전투까지의 자원 소모 압박을 줄인다. 보스전 뒤 자원 회복은 큰 적을 물리친 뒤에만 적용되는 방식이다.","accent":"#667E94","tab":"#528982","facet":"게임·상호작용","bookmark":"전투·경쟁","entry_url":"cards/MEJE-KW-001092/index.html"},{"id":"MEJE-KW-001093","row_version":1,"title":"방과 후 교실 청소 당번","original":"After-School Cleaning Duty","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"수업이 끝난 뒤 학생들이 교실에 남아 청소하는 학교 생활의 관습. 다른 학생들이 떠난 공간에서 인물들이 대화하거나 뜻밖의 사건을 만날 계기를 만든다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-001093/index.html"},{"id":"MEJE-KW-001094","row_version":1,"title":"원작 종료 뒤 이어지는 후속 쇼","original":"After Show","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"기존 프로그램이 끝난 뒤 익숙한 출연진이나 인물을 중심으로 이름과 구성을 바꿔 계속하는 방송 제작 방식. 원작의 연속성과 새 프로그램의 독립성 사이에서 기대가 형성된다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-001094/index.html"},{"id":"MEJE-KW-001095","row_version":1,"title":"종교를 이유로 거절하기","original":"Against My Religion","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 어떤 요청을 받아들이지 않으면서 자신의 종교적 신념을 이유로 드는 대사와 상황. 실제 신념에 따른 선택인지 편의를 위한 구실인지는 작품 속 맥락으로 구분한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-001095/index.html"},{"id":"MEJE-KW-001096","row_version":1,"title":"소속 집단의 기대를 거스름","original":"Against the Grain","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"인물이 가족이나 공동체가 자신에게 당연하다고 여기는 역할 대신 다른 길을 고르는 이야기. 개인의 욕구와 집단 규범 사이의 마찰이 변화의 계기가 된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-001096/index.html"},{"id":"MEJE-KW-001097","row_version":1,"title":"석양을 향해 다짐하기","original":"Against the Setting Sun","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이나 팀이 지는 해를 마주한 채 앞으로 이룰 목표를 함께 말하는 장면. 하루의 끝을 새로운 약속의 시작과 겹쳐 보여 주는 시각 연출이다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-001097/index.html"},{"id":"MEJE-KW-001098","row_version":1,"title":"같은 말을 다른 감정으로 반복","original":"Again with Feeling","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23","ML-T01962"],"summary":"인물이 방금 한 말을 다시 말하면서 억양과 감정을 바꿔 뒤늦게 깨달은 뜻을 드러내는 대사 방식. 문장은 같아도 두 번째 발화가 사건의 무게를 바꾼다.","accent":"#7C808E","tab":"#7D8FA3","facet":"서술·언어·정보","bookmark":"대사 기능","entry_url":"cards/MEJE-KW-001098/index.html"},{"id":"MEJE-KW-001099","row_version":1,"title":"나이에 따라 달리 읽히는 고뇌","original":"Age-Appropriate Angst","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":null,"parent_id":null,"tag_path":["ML-F30"],"summary":"비슷한 상실이나 좌절이라도 인물의 나이에 따라 관객이 그 반응을 다르게 받아들이는 수용 방식. 나이가 감정의 정당성을 결정한다는 뜻은 아니며 작품의 연출과 기대가 함께 작동한다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"분류축","entry_url":"cards/MEJE-KW-001099/index.html"},{"id":"MEJE-KW-001100","row_version":1,"title":"나이 변화를 잇는 화면 전환","original":"Age Cut","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22","ML-T01908"],"summary":"같은 인물의 젊은 모습과 나이 든 모습을 위치나 동작을 맞춰 연결하는 편집. 긴 시간을 한 번의 전환으로 압축해 세월의 흐름을 보여 준다.","accent":"#688397","tab":"#AF8665","facet":"시각·공간 연출","bookmark":"편집·연결","entry_url":"cards/MEJE-KW-001100/index.html"},{"id":"MEJE-KW-001101","row_version":1,"title":"나이 변화로 다시 보이는 연애 관계","original":"Age-Down Romance","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10","ML-T00979"],"summary":"인물의 몸이나 겉모습의 나이가 달라진 뒤 다른 사람과의 호감 관계가 새로 문제 되는 설정. 기억과 실제 경험, 겉모습의 차이가 관계의 경계와 동의에 어떤 영향을 주는지 살펴야 한다.","accent":"#9D7C82","tab":"#778F70","facet":"관계","bookmark":"연애 상태","entry_url":"cards/MEJE-KW-001101/index.html"},{"id":"MEJE-KW-001102","row_version":1,"title":"상대의 나이를 과장해 부르기","original":"Age Exaggeration","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"인물이 조금 더 나이가 많은 상대를 지나치게 늙은 사람처럼 부르는 말버릇. 말하는 사람의 기준과 두 인물의 거리감이 드러나며 웃음이나 갈등을 만든다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-001102/index.html"},{"id":"MEJE-KW-001103","row_version":1,"title":"나이 차를 계산으로 정당화","original":"Age-Gap Algebra","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"두 사람의 연령 차이가 적절한지 숫자 규칙으로 판단하려는 대사나 사고방식. 계산이 관계의 맥락과 당사자의 선택을 대신할 수 없다는 긴장을 만들 수 있다. 나이 차 연애와 함께 나타난다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-001103/index.html"},{"id":"MEJE-KW-001104","row_version":1,"title":"나이 차 연애","original":"Age-Gap Romance","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10","ML-T00979"],"summary":"연애하는 두 인물의 나이 차이가 주변의 시선이나 생활 단계의 차이를 통해 두드러지는 관계. 연령 숫자만으로 관계를 평가할 수 없으며, 미성년자와 성인이 엮이는 경우에는 권력 차이와 동의 문제를 별도로 살펴야 한다.","accent":"#9D7C82","tab":"#778F70","facet":"관계","bookmark":"연애 상태","entry_url":"cards/MEJE-KW-001104/index.html"},{"id":"MEJE-KW-001105","row_version":1,"title":"나이와 어긋난 공연 내용","original":"Age-Inappropriate Art","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"어린 인물이 자신에게 기대되는 범위보다 무겁거나 성숙한 노래와 연기를 선보여 주변을 놀라게 하는 장면. 공연의 내용뿐 아니라 어른들이 그 인물을 바라보는 방식도 드러낸다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-001105/index.html"},{"id":"MEJE-KW-001106","row_version":1,"title":"나이 규범에서 벗어난 옷차림","original":"Age-Inappropriate Dress","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09","ML-T00956","ML-T00961"],"summary":"인물이 주변에서 자기 나이에 어울린다고 여기는 옷차림과 다른 복장을 택하는 모습. 실제 나이보다 사회적 기대가 어떻게 외형을 평가하는지를 보여 준다.","accent":"#7B7594","tab":"#AF8665","facet":"인물","bookmark":"나이와 외형의 불일치","entry_url":"cards/MEJE-KW-001106/index.html"},{"id":"MEJE-KW-001107","row_version":1,"title":"나이를 밝히기 꺼리는 마음","original":"Age Insecurity","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 자신의 나이를 숨기거나 숫자가 드러나는 상황에서 불편함을 느끼는 심리. 젊음과 성공에 대한 주변의 기대가 그 반응에 영향을 줄 수 있다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-001107/index.html"},{"id":"MEJE-KW-001108","row_version":1,"title":"역할에 따라 달라 보이는 나이","original":"Age Is Relative","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물의 실제 연령보다 책임감과 능력, 집단 안의 위치에 따라 더 어리거나 성숙하게 보이도록 그리는 연출. 외형이 서사적 역할을 전달하는 방식이다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-001108/index.html"},{"id":"MEJE-KW-001109","row_version":1,"title":"나이가 늘지 않는 생일 이야기","original":"Ageless Birthday Episode","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"생일을 중심으로 한 에피소드가 지나도 인물의 새 나이가 언급되지 않거나 이후 이야기의 나이에 반영되지 않는 연속물 관습. 축하 행사는 남기고 성장에 따른 변화는 유예한다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-001109/index.html"},{"id":"MEJE-KW-001110","row_version":1,"title":"나이를 바꾼 각색","original":"Age Lift","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27","ML-T02261","ML-T02262"],"summary":"원작의 인물을 다른 매체나 새 버전으로 옮기면서 나이를 높이거나 낮추는 변화. 관계와 사건의 의미가 나이에 따라 달라질 수 있어 원작 각색의 한 형태로 다룬다.","accent":"#7F8A85","tab":"#8B739C","facet":"메타·제작·유통","bookmark":"원작 각색","entry_url":"cards/MEJE-KW-001110/index.html"},{"id":"MEJE-KW-001111","row_version":1,"title":"기이한 설명을 먼저 믿는 인물","original":"Agent Mulder","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"기이한 사건을 만났을 때 알려진 설명 밖의 가능성을 먼저 받아들이는 인물상. 기이한 일을 일상적으로 설명하는 인물과 함께 놓이면 같은 증거를 두고 다른 해석이 충돌한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-001111/index.html"},{"id":"MEJE-KW-001112","row_version":1,"title":"화려한 외양의 유능한 남성 인물","original":"Agent Peacock","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"꾸밈과 섬세한 표현을 즐기면서도 맡은 일에 능숙한 남성 인물상. 외양과 능력을 반대되는 성질처럼 보는 주변의 기대를 흔든다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-001112/index.html"},{"id":"MEJE-KW-001113","row_version":1,"title":"상대 조직을 자극하는 잠입 인물","original":"Agent Provocateur","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"상대 집단 안에 숨어 들어가 위험한 행동이나 분열을 부추기는 인물. 진짜 소속과 겉으로 보이는 충성의 차이가 음모의 핵심이 된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-001113/index.html"},{"id":"MEJE-KW-001114","row_version":1,"title":"기이한 일을 일상적으로 설명하는 인물","original":"Agent Scully","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"기이한 사건도 익숙한 원인으로 설명하려는 인물상. 기이한 설명을 먼저 믿는 인물과 짝을 이루면 증거를 받아들이는 기준 자체가 갈등이 된다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-001114/index.html"},{"id":"MEJE-KW-001115","row_version":1,"title":"요원끼리의 데이트","original":"Agents Dating","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10","ML-T00979"],"summary":"비슷한 임무를 맡은 두 요원이 데이트하거나 연애하는 관계. 사적인 신뢰와 직업상 비밀, 임무의 우선순위가 한 관계 안에서 부딪힌다.","accent":"#9D7C82","tab":"#778F70","facet":"관계","bookmark":"연애 상태","entry_url":"cards/MEJE-KW-001115/index.html"},{"id":"MEJE-KW-001116","row_version":1,"title":"파충류 문명이 앞선 시대","original":"Age of Reptiles","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"현재의 지배 세력보다 오래전에 파충류형 존재가 세계를 이끌었다는 허구의 역사 설정. 유적과 전승을 통해 지금의 세계가 이전 시대 위에 세워졌음을 보여 준다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-001116/index.html"},{"id":"MEJE-KW-001117","row_version":1,"title":"시대를 내세운 제목","original":"Age of Titles","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"작품이나 구호의 제목에 특정한 '시대'의 시작과 성격을 드러내는 말을 넣는 작명 관습. 제목만으로 변화의 규모와 시대적 분위기를 암시한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-001117/index.html"},{"id":"MEJE-KW-001118","row_version":1,"title":"나이의 흐름을 따라가는 노래","original":"Age-Progression Song","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"한 사람의 삶이나 긴 시간의 변화를 여러 연령대의 장면으로 나누어 노래하는 구성. 각 절이 서로 다른 시기를 지나며 반복되는 후렴이 공통된 주제를 묶는다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-001118/index.html"},{"id":"MEJE-KW-001119","row_version":1,"title":"나이에 묶인 능력","original":"Age-Restricted Ability","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"특정 나이대에만 특별한 힘을 얻거나 유지할 수 있는 세계관 규칙. 성장과 노화가 곧 능력의 기회와 상실을 뜻해 세대 사이의 긴장을 만든다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-001119/index.html"},{"id":"MEJE-KW-001120","row_version":1,"title":"한 배우가 다른 나이를 연기","original":"Age-Shifted Actor","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27","ML-T02277","ML-T02278"],"summary":"한 배우가 분장과 몸짓을 바꿔 같은 인물의 젊은 시절이나 노년을 연기하는 제작 방식. 배우의 연속성을 유지하며 이야기 속 시간을 넓힌다.","accent":"#7F8A85","tab":"#528982","facet":"메타·제작·유통","bookmark":"캐스팅 관행","entry_url":"cards/MEJE-KW-001120/index.html"},{"id":"MEJE-KW-001121","row_version":1,"title":"나이별 음식이라는 고정 이미지","original":"Age-Stereotypical Food","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"어떤 음식을 어린이나 어른의 것이라고 여기는 사회적 이미지. 인물이 그 기대와 다른 음식을 고를 때 취향보다 나이 규범이 먼저 평가되는 모습을 드러낸다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-001121/index.html"},{"id":"MEJE-KW-001122","row_version":1,"title":"젊은 시절을 배우의 친족이 연기","original":"Age Them Down, Cast Their Kid","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27","ML-T02277","ML-T02278"],"summary":"한 인물의 어린 시절을 그 인물을 맡은 배우의 자녀나 가까운 친족이 연기하는 캐스팅 방식. 닮은 외형을 활용하면서도 두 시기의 연기를 연결한다.","accent":"#7F8A85","tab":"#528982","facet":"메타·제작·유통","bookmark":"캐스팅 관행","entry_url":"cards/MEJE-KW-001122/index.html"},{"id":"MEJE-KW-001123","row_version":1,"title":"젊음 없이 이어지는 불멸","original":"Age Without Youth","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13","ML-T01202","ML-T01207"],"summary":"죽지 않는 몸을 얻었지만 노화는 멈추지 않아 시간이 지날수록 쇠약해지는 불멸 설정. 영원한 생명이 영원한 젊음과 같지 않다는 대가를 드러낸다.","accent":"#497A73","tab":"#528982","facet":"세계관·규칙","bookmark":"불멸의 조건","entry_url":"cards/MEJE-KW-001123/index.html"},{"id":"MEJE-KW-001124","row_version":1,"title":"편견을 고집하며 타인을 재단","original":"Aggressive Categorism","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"인물의 실제 행동보다 성별이나 나이, 출신 같은 범주에 대한 고정관념을 우선해 판단하는 태도. 반례를 만나도 편견을 유지하려는 모습이 차별의 작동 방식을 드러낸다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-001124/index.html"},{"id":"MEJE-KW-001125","row_version":1,"title":"협상 자리에서 무력을 꺼냄","original":"Aggressive Negotiations","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07","ML-T00757","ML-T00759"],"summary":"대화로 합의할 듯 보이던 인물이 갑자기 무력을 앞세워 상대를 압박하는 장면. 협상의 약속이 깨지는 순간 힘의 균형과 신뢰가 함께 무너진다.","accent":"#9B7160","tab":"#A58A4E","facet":"사건·행동","bookmark":"협상","entry_url":"cards/MEJE-KW-001125/index.html"},{"id":"MEJE-KW-001126","row_version":1,"title":"적극적 플레이를 유도하는 보상","original":"Aggressive Play Incentive","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25","ML-T02133"],"summary":"게임이 기다리거나 숨는 행동보다 앞으로 나아가 위험을 감수하는 행동에 회복이나 자원을 주는 설계. 보상의 위치가 플레이어의 속도와 전투 방식을 바꾼다.","accent":"#667E94","tab":"#79866C","facet":"게임·상호작용","bookmark":"보상·실패","entry_url":"cards/MEJE-KW-001126/index.html"},{"id":"MEJE-KW-001127","row_version":1,"title":"평소와 친밀한 관계의 주도성이 다른 인물","original":"Aggressive Submissive","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"평소에는 강하게 자기 뜻을 드러내지만 성인 사이의 친밀한 관계에서는 상대에게 주도권을 맡기기를 선호하는 인물상. 성격과 동의, 관계의 역할을 같은 것으로 단순화하지 않는다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-001127/index.html"},{"id":"MEJE-KW-001128","row_version":1,"title":"반려동물의 노화를 마주함","original":"Aging Pet Angst","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"함께 지낸 동물이 늙어 예전처럼 움직이지 못하는 모습을 보며 인물이 상실을 예감하는 감정선. 오래 쌓인 일상과 남은 시간을 어떻게 보내는지가 이야기의 중심이 된다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-001128/index.html"},{"id":"MEJE-KW-001129","row_version":1,"title":"유행을 따라잡으려 애쓰는 장년 인물","original":"Aging Would-Be Hipster","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"새로운 말투와 유행을 과하게 흉내 내며 여전히 젊은 집단에 속하고 싶어 하는 장년 인물상. 나이를 웃음의 대상으로 삼기보다 소속되고 싶은 마음을 함께 볼 수 있다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-001129/index.html"},{"id":"MEJE-KW-001130","row_version":1,"title":"화난 마음에 물건을 짓밟음","original":"Agitated Item Stomping","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07","ML-T00776","ML-T00785"],"summary":"분노를 참지 못한 인물이 가까운 물건을 발로 거칠게 짓밟는 행동. 대상 자체보다 통제하지 못한 감정의 크기를 보여 주는 장면이다.","accent":"#9B7160","tab":"#7D8FA3","facet":"사건·행동","bookmark":"파괴","entry_url":"cards/MEJE-KW-001130/index.html"},{"id":"MEJE-KW-001131","row_version":1,"title":"배에 입은 상처로 길어지는 위기","original":"Agonizing Stomach Wound","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"인물이 배에 심한 상처를 입은 뒤 바로 장면이 끝나지 않고 고통과 구조의 기다림이 이어지는 서사. 상처의 의학적 결과를 일반화하기보다 이야기 속 위기의 지속에 초점을 둔다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-001131/index.html"},{"id":"MEJE-KW-001132","row_version":1,"title":"고통을 가하는 광선 무기","original":"Agony Beam","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16","ML-T01408"],"summary":"적을 즉시 없애기보다 강한 고통으로 굴복시키는 허구의 광선 무기나 능력. 악역의 잔혹함과 포로의 저항을 드러내는 소품으로 쓰인다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"무기·방어구","entry_url":"cards/MEJE-KW-001132/index.html"},{"id":"MEJE-KW-001133","row_version":1,"title":"발의 고통을 강조하는 장면","original":"Agony of the Feet","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07","ML-T00795","ML-T00800"],"summary":"발이나 발가락에 가해진 고통이 인물의 행동을 멈추게 하거나 장면의 긴장을 바꾸는 사건. 작은 신체 부위의 통증을 통해 위험이나 불운을 즉각 전한다.","accent":"#9B7160","tab":"#79866C","facet":"사건·행동","bookmark":"부상","entry_url":"cards/MEJE-KW-001133/index.html"},{"id":"MEJE-KW-001134","row_version":1,"title":"차이를 인정하고 논쟁을 멈춤","original":"Agree to Disagree","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23","ML-T01962"],"summary":"서로의 생각이 달라 합의하지 못한 인물들이 더 다투지 않기로 말하는 대화 방식. 관계를 지키는 선택일 수도 있고 중요한 문제를 미루는 회피일 수도 있다.","accent":"#7C808E","tab":"#7D8FA3","facet":"서술·언어·정보","bookmark":"대사 기능","entry_url":"cards/MEJE-KW-001134/index.html"},{"id":"MEJE-KW-001135","row_version":1,"title":"농업 특화 행성","original":"Agri World","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"다른 지역이나 행성에 먹거리와 원료를 공급하는 일이 사회의 중심이 된 세계. 생산지와 소비지가 멀리 떨어진 구조가 정치와 물류, 주민의 삶에 영향을 준다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-001135/index.html"},{"id":"MEJE-KW-001136","row_version":1,"title":"헛기침으로 눈치 주기","original":"Ahem","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23","ML-T01962"],"summary":"말 대신 의도적인 헛기침으로 상대의 주의를 끌거나 그가 놓친 상황을 알려 주는 신호. 누가 듣고 있는지, 무엇을 말하지 말아야 하는지를 짧은 소리로 드러낸다.","accent":"#7C808E","tab":"#7D8FA3","facet":"서술·언어·정보","bookmark":"대사 기능","entry_url":"cards/MEJE-KW-001136/index.html"},{"id":"MEJE-KW-001137","row_version":1,"title":"병고 속에서 거칠어지는 인물","original":"Ailment-Induced Cruelty","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"오랜 병이나 고통을 겪는 인물이 주변 사람에게 날카로운 말과 행동을 보이는 서사. 모든 환자를 그렇게 그리는 일반화가 되지 않도록 그 인물의 사정과 관계의 변화를 함께 살핀다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-001137/index.html"},{"id":"MEJE-KW-001138","row_version":1,"title":"뿔에만 있는 약점","original":"Aim for the Horn","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"뿔 달린 적의 몸보다 뿔을 맞혔을 때 결정적인 변화가 일어나는 전투 규칙. 눈에 띄는 외형 하나가 적의 약점을 알리는 단서가 된다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-001138/index.html"},{"id":"MEJE-KW-001139","row_version":1,"title":"행복을 찾지만 방법을 모름","original":"Aimlessly Seeking Happiness","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"인물이 행복해지고 싶다는 마음은 분명하지만 무엇을 바꾸어야 할지 알지 못하는 심리. 여러 목표를 좇다 멈추는 과정에서 자신이 원하는 삶의 형태를 묻는다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-001139/index.html"},{"id":"MEJE-KW-001140","row_version":1,"title":"자존심을 내려놓고 애원함","original":"Ain't Too Proud to Beg","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"평소 굽히지 않던 인물이 절박한 상황에서 상대에게 간청하는 행동. 체면보다 지키고 싶은 사람이나 목적이 더 중요해졌음을 보여 준다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-001140/index.html"},{"id":"MEJE-KW-001141","row_version":1,"title":"바람의 힘을 빌린 도약","original":"Air-Aided Acrobatics","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25","ML-T02070","ML-T02071"],"summary":"게임이나 환상적 장면에서 상승 기류와 돌풍이 인물의 점프를 도와 먼 틈을 넘게 하는 장치. 환경의 움직임이 이동 경로를 여는 규칙으로 쓰인다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"이동 조작","entry_url":"cards/MEJE-KW-001141/index.html"},{"id":"MEJE-KW-001142","row_version":1,"title":"하늘을 나는 항공모함","original":"Airborne Aircraft Carrier","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16","ML-T01454","ML-T01460"],"summary":"다른 비행체를 싣고 운용할 수 있는 거대한 비행 기지. 하늘의 이동 거점이자 성채로 등장해 공중 전투의 무대 규모를 넓힌다.","accent":"#8E8263","tab":"#7D8FA3","facet":"사물·도구·자원","bookmark":"항공기","entry_url":"cards/MEJE-KW-001142/index.html"},{"id":"MEJE-KW-001143","row_version":1,"title":"비행형 장거리 포격 유닛","original":"Airborne Artillery","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25","ML-T02106"],"summary":"하늘에 머물며 먼 거리에서 공격하는 게임 속 전투 유닛. 비행과 포격이 결합해 전장에 새로운 위협의 방향을 만든다.","accent":"#667E94","tab":"#528982","facet":"게임·상호작용","bookmark":"전투·경쟁","entry_url":"cards/MEJE-KW-001143/index.html"},{"id":"MEJE-KW-001144","row_version":1,"title":"날아다니는 하급 적","original":"Airborne Mook","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25","ML-T02106"],"summary":"지상의 일반 적과 달리 비행하거나 떠다니며 플레이어의 움직임을 방해하는 하급 적. 높이 차이 때문에 익숙한 공격과 회피의 리듬이 바뀐다.","accent":"#667E94","tab":"#528982","facet":"게임·상호작용","bookmark":"전투·경쟁","entry_url":"cards/MEJE-KW-001144/index.html"},{"id":"MEJE-KW-001145","row_version":1,"title":"공기를 가두는 역장","original":"Air Containment Field","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"사람이나 물체는 지나가게 하면서 실내의 공기는 빠져나가지 않도록 설정된 허구의 장벽. 우주 정거장과 선박의 열린 통로를 가능하게 하는 세계관 기술이다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-001145/index.html"},{"id":"MEJE-KW-001146","row_version":1,"title":"보이지 않는 기타 연주","original":"Air Guitar","aliases":[],"kind":"keyword","facet_id":"ML-F26","node_kind":null,"parent_id":null,"tag_path":["ML-F26"],"summary":"실제 악기 없이 몸짓으로 기타를 연주하는 흉내를 내는 행동. 음악에 몰입한 인물의 취향과 기분을 짧은 동작으로 드러낸다.","accent":"#9D806B","tab":"#9A6A55","facet":"공연·참여·팬덤","bookmark":"분류축","entry_url":"cards/MEJE-KW-001146/index.html"},{"id":"MEJE-KW-001147","row_version":1,"title":"닿지 않는 어색한 포옹","original":"Air Hugging","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"친밀함을 표현하려 하지만 몸을 가까이하지 못해 포옹이 어색하게 멈추는 장면. 특히 남성에게 애정 표현을 금기시하는 기대가 있는지 관계의 맥락에서 읽을 수 있다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-001147/index.html"},{"id":"MEJE-KW-001148","row_version":1,"title":"공중에서 정면으로 맞부딪힘","original":"Air Jousting","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07","ML-T00776","ML-T00778"],"summary":"비행 중인 두 인물이 서로를 향해 돌진해 정면 충돌이나 한 번의 교차로 승부를 내는 장면. 속도와 방향을 단순하게 맞세워 대결의 순간을 강조한다.","accent":"#9B7160","tab":"#7D8FA3","facet":"사건·행동","bookmark":"전투","entry_url":"cards/MEJE-KW-001148/index.html"},{"id":"MEJE-KW-001149","row_version":1,"title":"비행기 날개처럼 팔을 벌리고 달림","original":"Airplane Arms","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 두 팔을 양옆으로 뻗고 달려 비행기를 흉내 내는 몸짓. 들뜬 마음이나 아이 같은 놀이를 실루엣 하나로 보여 준다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-001149/index.html"},{"id":"MEJE-KW-001150","row_version":1,"title":"멀어지는 비행기로 그리는 짝사랑","original":"Airplane of Love","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"좋아하는 사람이 닿기 어려운 곳에 있다고 느낄 때 멀어지는 비행기를 바라보는 장면. 하늘로 사라지는 물체가 마음의 거리와 놓친 순간을 대신한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-001150/index.html"},{"id":"MEJE-KW-001151","row_version":1,"title":"여행길에 집어 드는 대중 소설","original":"Airport Novel","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":null,"parent_id":null,"tag_path":["ML-F30"],"summary":"공항이나 이동 중에 가볍게 읽으려고 고르는 이야기책의 이미지. 작품의 가치를 단정하기보다 읽는 장소와 시간의 맥락이 만드는 기대를 설명한다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"분류축","entry_url":"cards/MEJE-KW-001151/index.html"},{"id":"MEJE-KW-001152","row_version":1,"title":"손가락 따옴표","original":"Air Quotes","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23","ML-T01962"],"summary":"말하는 사람이 두 손가락으로 따옴표 모양을 만들어 특정 단어에 거리를 두거나 빈정거림을 표시하는 몸짓. 같은 낱말도 몸짓이 붙으면 믿기 어렵거나 임시로 부르는 말처럼 들린다.","accent":"#7C808E","tab":"#7D8FA3","facet":"서술·언어·정보","bookmark":"대사 기능","entry_url":"cards/MEJE-KW-001152/index.html"},{"id":"MEJE-KW-001153","row_version":1,"title":"불가능해 보이는 비행 임무","original":"Airstrike: Impossible","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"비행체가 본래 다니기 어려운 좁거나 위험한 공간을 통과해야 목표에 닿는 절정의 임무. 조종 실력과 시간의 압박이 한 장면에 모인다. 좁은 지형을 가르는 공중 추격은 그 임무가 추격전으로 펼쳐지는 경우다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-001153/index.html"},{"id":"MEJE-KW-001154","row_version":1,"title":"정복지에 새 번호를 붙임","original":"Airstrip One","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"정복 세력이 지역의 본래 이름을 지우고 번호나 행정 명칭으로 다시 부르는 통치 방식. 지명을 바꾸는 일이 주민의 기억과 소속감을 억누르는 상징이 된다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-001154/index.html"},{"id":"MEJE-KW-001155","row_version":1,"title":"환기구로 이어지는 잠입 통로","original":"Air-Vent Passageway","aliases":[],"kind":"keyword","facet_id":"ML-F14","node_kind":null,"parent_id":null,"tag_path":["ML-F14"],"summary":"허구의 건물에서 환기구가 방과 복도를 잇는 통로처럼 묘사되는 공간 관습. 좁은 길이 탈출과 잠입의 지름길로 쓰이며 실제 시설의 크기와 구조는 이야기의 편의에 맞게 단순화된다.","accent":"#68838D","tab":"#9A6A55","facet":"시공간·환경","bookmark":"분류축","entry_url":"cards/MEJE-KW-001155/index.html"},{"id":"MEJE-KW-001156","row_version":1,"title":"떠난 사람의 비행기를 알아봄","original":"Air Voyance","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 공항 밖에서 멀어지는 여러 비행기 가운데 좋아하는 사람이 탄 기체를 곧바로 알아본 듯 바라보는 장면. 현실의 식별 가능성보다 이별의 감정 전달이 앞선다. 멀어지는 비행기로 그리는 짝사랑과 함께 나타날 수 있다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-001156/index.html"},{"id":"MEJE-KW-001157","row_version":1,"title":"아카식 기록","original":"Akashic Records","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"세계의 지식과 기억이 한곳에 담겨 있다고 여겨지는 신비한 기록 설정. 인물이 그 기록에 닿는 방식이 비밀의 발견과 지식의 한계를 이야기한다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-001157/index.html"},{"id":"MEJE-KW-001158","row_version":1,"title":"본명 대신 쓰는 감독 가명","original":"Alan Smithee","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"제작 과정에서 감독의 본명 대신 공동의 가명을 크레디트에 올리는 관습을 가리키는 이름. 이름이 빠진 이유보다 작품과 창작자의 관계를 어떻게 표시하는지가 핵심이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-001158/index.html"},{"id":"MEJE-KW-001159","row_version":1,"title":"경보로 구조를 요청함","original":"Alarm SOS","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07","ML-T00776","ML-T00782"],"summary":"도움을 부를 다른 방법이 막힌 인물이 가까운 경보 장치를 이용해 자신의 위치와 위기를 알리는 사건. 경보의 본래 목적과 인물의 절박한 목적이 어긋난다.","accent":"#9B7160","tab":"#7D8FA3","facet":"사건·행동","bookmark":"구조","entry_url":"cards/MEJE-KW-001159/index.html"},{"id":"MEJE-KW-001160","row_version":1,"title":"미움받던 인물의 죽음에 연민","original":"Alas, Poor Scrappy","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":null,"parent_id":null,"tag_path":["ML-F30"],"summary":"평소 관객의 호감을 얻지 못하던 인물이 마지막 순간의 연출 때문에 뜻밖의 연민을 불러일으키는 수용 변화. 악역의 최후에 연민과는 이전의 비호감이 꼭 악행 때문은 아니라는 점이 다르다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"분류축","entry_url":"cards/MEJE-KW-001160/index.html"},{"id":"MEJE-KW-001161","row_version":1,"title":"악역의 최후에 연민","original":"Alas, Poor Villain","aliases":[],"kind":"keyword","facet_id":"ML-F30","node_kind":null,"parent_id":null,"tag_path":["ML-F30"],"summary":"악역의 최후가 그가 남긴 해악을 지우지 않으면서도 관객에게 슬픔이나 복잡한 감정을 남기는 장면. 미움받던 인물의 죽음에 연민보다 인물의 악행과 연민의 공존이 중심이다.","accent":"#8B817D","tab":"#9A6A55","facet":"대상·수용맥락","bookmark":"분류축","entry_url":"cards/MEJE-KW-001161/index.html"},{"id":"MEJE-KW-001162","row_version":1,"title":"유해를 품고 애도하기","original":"Alas, Poor Yorick","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"잃은 사람의 머리나 남겨진 유해를 품고 슬퍼하는 시각적 장면. 가까이 둘 수 없는 존재를 마지막으로 안으려는 마음을 한 동작에 모은다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-001162/index.html"},{"id":"MEJE-KW-001163","row_version":1,"title":"백색증 인물을 괴물처럼 그리기","original":"Albinos Are Freaks","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"백색증이 있는 인물의 외형을 두려움이나 초자연적 힘의 표지로만 사용하는 표현 관습. 실제 사람의 특징을 기이함과 연결하는 편견이므로 인물의 성격과 삶을 외형 하나로 환원하지 않도록 살핀다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001163/index.html"},{"id":"MEJE-KW-001164","row_version":1,"title":"앨범의 마무리 곡","original":"Album Closure","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24","ML-T02018"],"summary":"앨범의 마지막 곡이 앞선 곡들의 분위기나 주제를 되짚으며 듣는 경험을 끝맺는 구성. 앨범 전체를 하나의 흐름으로 느끼게 한다. 앨범의 도입 곡과 순서상 짝을 이룬다.","accent":"#8A7893","tab":"#8B739C","facet":"소리·음악","bookmark":"음악의 기능","entry_url":"cards/MEJE-KW-001164/index.html"},{"id":"MEJE-KW-001165","row_version":1,"title":"분량 채우기로 받아들여지는 앨범 곡","original":"Album Filler","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"앨범 안에서 주제나 완성도 면에서 핵심 곡에 비해 덜 중요하게 여겨지는 곡. 그런 평가는 듣는 사람과 제작 의도에 따라 달라질 수 있다. 앨범의 구성에 대한 평가를 보여 준다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-001165/index.html"},{"id":"MEJE-KW-001166","row_version":1,"title":"앨범의 도입 곡","original":"Album Intro Track","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24","ML-T02018"],"summary":"앨범의 첫머리에서 분위기나 주제를 미리 알리는 짧은 곡이나 도입 구간. 이후의 곡을 듣는 기대를 만들며 앨범의 마무리 곡과 순서상 짝을 이룬다.","accent":"#8A7893","tab":"#8B739C","facet":"소리·음악","bookmark":"음악의 기능","entry_url":"cards/MEJE-KW-001166/index.html"},{"id":"MEJE-KW-001168","row_version":1,"title":"앨범에서 따로 내세운 싱글곡","original":"Album Single","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27","ML-T02293"],"summary":"앨범에 실린 곡 가운데 별도의 발매나 홍보 대상으로 앞세운 트랙. 개별 곡의 인지도와 앨범 전체의 흐름이 서로 다른 방식으로 소비된다.","accent":"#7F8A85","tab":"#A07A87","facet":"메타·제작·유통","bookmark":"홍보·주변물","entry_url":"cards/MEJE-KW-001168/index.html"},{"id":"MEJE-KW-001169","row_version":1,"title":"가사에 나타나는 앨범 제목","original":"Album Title Drop","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"앨범 제목이 곡의 제목이 아니라 가사 속 한 구절로 등장하는 방식. 듣는 사람이 그 구절을 만나는 순간 앨범의 제목과 노래의 연결을 새로 알아차린다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-001169/index.html"},{"id":"MEJE-KW-001170","row_version":1,"title":"연금술의 네 원소 정령","original":"Alchemic Elementals","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12","ML-T01123","ML-T01125"],"summary":"공기와 물, 땅, 불에 각각 대응하는 존재를 한 묶음으로 구성한 환상 세계의 종족·정령 설정. 원소의 차이가 외형과 성격, 역할의 차이로 표현된다. 정령의 한 계열이다.","accent":"#62816F","tab":"#A58A4E","facet":"존재·종족","bookmark":"정령","entry_url":"cards/MEJE-KW-001170/index.html"},{"id":"MEJE-KW-001171","row_version":1,"title":"딸꾹질로 취기를 알림","original":"Alcohol Hic","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 딸꾹질을 하자 주변과 관객이 술을 마셨음을 알아채는 연출 관습. 실제 음주 상태를 판단하는 기준이 아니라 극중에서 쓰이는 간단한 신호다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-001171/index.html"},{"id":"MEJE-KW-001172","row_version":1,"title":"음주 문제를 안고 있는 부모","original":"Alcoholic Parent","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10","ML-T00970","ML-T00971"],"summary":"부모의 반복적인 음주가 돌봄과 가족 관계에 갈등을 만드는 서사. 음주 문제만으로 그 인물의 모든 행동이나 학대 여부를 단정하지 않고 각 가족의 상황을 따로 그린다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"부모와 자녀","entry_url":"cards/MEJE-KW-001172/index.html"},{"id":"MEJE-KW-001173","row_version":1,"title":"음주가 성적 지향을 바꾼 듯 그리기","original":"Alcohol-Induced Bisexuality","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"평소와 다른 상대에게 끌리는 모습을 술 탓으로만 처리하는 이야기 관습. 성적 지향을 일시적 장난으로 축소하는 표현인지, 인물의 원래 마음을 드러내는 장면인지 구분해 살핀다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001173/index.html"},{"id":"MEJE-KW-001174","row_version":1,"title":"음주 뒤 무모한 행동","original":"Alcohol-Induced Idiocy","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"술을 마신 인물이 평소라면 하지 않을 성급한 선택을 해 사건을 키우는 흐름. 행동의 결과와 책임을 어떻게 다루는지가 웃음과 비판의 방향을 정한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-001174/index.html"},{"id":"MEJE-KW-001175","row_version":1,"title":"술을 연료처럼 쓰는 허구적 장면","original":"Alcohol Is Gasoline","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"술을 기계의 연료로 부어 작동하게 하거나 지나치게 강한 술을 연료에 빗대는 과장된 표현. 실제 사용법이 아니라 허구의 농담과 세계관 관습으로 설명한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001175/index.html"},{"id":"MEJE-KW-000072","row_version":1,"title":"동행인을 지위의 장식처럼 과시","original":"A Lady on Each Arm","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 양옆의 동행인을 자신의 인기나 지위를 보여 주는 장식처럼 데리고 등장하는 연출. 등장 장면 하나로 허영이나 권력관을 드러내지만, 동행인의 인격을 지우는 대상화가 함께 나타날 수 있다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-000072/index.html"},{"id":"MEJE-KW-001176","row_version":1,"title":"시공간 굴절 항행","original":"Alcubierre Drive","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17","ML-T01490","ML-T01492"],"summary":"우주선 자체의 속도를 높이는 대신 주변 시공간의 형태를 바꾸어 먼 거리를 건넌다는 가상 항행 방식. 작품에서는 이동 거리와 시간의 제약을 완화하는 설정 장치로 쓰인다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"초고속 이동","entry_url":"cards/MEJE-KW-001176/index.html"},{"id":"MEJE-KW-001177","row_version":1,"title":"눈치챔의 번쩍임","original":"Alertness Blink","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"인물이 무언가를 알아차리는 순간 짧은 빛, 기호 또는 소리를 덧붙이는 연출. 내면의 인지 변화를 대사 없이 즉각 전달한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-001177/index.html"},{"id":"MEJE-KW-001178","row_version":1,"title":"수치 누적형 서사 분기","original":"Algorithmic Story Branching","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25","ML-T02125","ML-T02126"],"summary":"개별 선택 하나보다 여러 행동에서 쌓인 수치나 성향을 판정해 후속 사건을 고르는 이야기 구조. 같은 장면도 이전 선택의 누적 결과에 따라 다른 의미로 이어질 수 있다.","accent":"#667E94","tab":"#A07A87","facet":"게임·상호작용","bookmark":"분기 선택","entry_url":"cards/MEJE-KW-001178/index.html"},{"id":"MEJE-KW-001179","row_version":1,"title":"앨리스 모티프 인용","original":"Alice Allusion","aliases":[],"kind":"keyword","facet_id":"ML-F29","node_kind":null,"parent_id":null,"tag_path":["ML-F29"],"summary":"이상한 나라의 앨리스를 떠올리게 하는 이름, 토끼굴, 카드나 거울 같은 표지를 통해 낯선 세계로의 진입을 암시하는 참조 방식. 단순한 이름 일치와 구분해 작품의 이미지가 실제로 서사에 작용하는지 본다.","accent":"#7B876E","tab":"#9A6A55","facet":"기원·전승·참조","bookmark":"분류축","entry_url":"cards/MEJE-KW-001179/index.html"},{"id":"MEJE-KW-001180","row_version":1,"title":"앨리스와 밥의 가상 대화자","original":"Alice and Bob","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"추상적인 규칙이나 상황을 설명할 때 두 가상 인물에게 역할을 나누어 주는 서술 관습. 인물 자체의 전기보다 누가 무엇을 알고 전달하는지를 명료하게 만드는 데 쓰인다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-001180/index.html"},{"id":"MEJE-KW-001181","row_version":1,"title":"외계 납치 피해자의 반격","original":"Alien Abductees Fight Back","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07","ML-T00776","ML-T00780"],"summary":"외계 존재에게 붙잡힌 인물이 탈출이나 협력을 통해 가해자에게 맞서는 전개. 외계 존재의 납치가 무력감에 초점을 두었다면 이 카드는 주도권을 되찾는 행동에 초점을 둔다.","accent":"#9B7160","tab":"#7D8FA3","facet":"사건·행동","bookmark":"납치","entry_url":"cards/MEJE-KW-001181/index.html"},{"id":"MEJE-KW-001182","row_version":1,"title":"외계 존재의 납치","original":"Alien Abduction","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07","ML-T00776","ML-T00780"],"summary":"외계 존재가 인간이나 다른 생명체를 뜻밖에 데려가 행방과 목적을 알 수 없게 만드는 사건. 귀환 이후 기억의 공백, 불신, 접촉의 비대칭이 이야기를 이끈다.","accent":"#9B7160","tab":"#7D8FA3","facet":"사건·행동","bookmark":"납치","entry_url":"cards/MEJE-KW-001182/index.html"}]}.cards;